// F-52 AC2 «במסך הקריאה קיימת פעולת סיום שמסמנת שהקריאה הושלמה» — «סיים קריאה» → «הקריאה הושלמה». Сохранение/счётчики НЕ требуются (D-06 открыта).
// @data: нажатие может писать данные в аккаунт (возврата нет и не требуется — счётчики молитв не меняются, D-06); записать в test_data прогона.
import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { goTab, hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

async function openChapter72() {
  if (hasDeepLinks()) {
    await openRoute('/tehilim/72');
  } else {
    await goTab('תהילים');
    const search = await (driver.isAndroid
      ? $('android=new UiSelector().className("android.widget.EditText")')
      : $('-ios class chain:**/XCUIElementTypeTextField'));
    await search.waitForDisplayed();
    await search.setValue('72');
    await (await byTextContains('לשלמה')).click();
  }
  await (await byText('תהילים ע״ב')).waitForDisplayed({ timeout: 20000 });
}

describe('Чтение תהילים', () => {
  afterEach(async () => { await toHome(); });

  it('TH-03 «סיים קריאה» → «הקריאה הושלמה» #6a86f7fca7ea @data', async () => {
    await openChapter72();
    await scrollToText('סיים קריאה', 15);
    await tapText('סיים קריאה');
    await expect(byTextContains('הקריאה הושלמה')).toBeDisplayed();
    await expectVisibleText('תהילים ע״ב');   // чтение не закрылось, экран тот же
  });
});
